import json
from typing import Any, Sequence


def _format_cell(value: Any) -> str:
    if value is None:
        return ""

    if isinstance(value, (dict, list, tuple)):
        try:
            return json.dumps(value, ensure_ascii=False, default=str)
        except TypeError:
            return str(value)

    return str(value)


def format_table(
    records: Sequence[Any],
    headers: Sequence[Any] | None = None,
    *,
    align: str = "left",
    separator: str = "  ",
) -> str:
    """Render a list of records as an aligned plain-text table.

    records can be:
      - dicts: column names come from keys
      - lists/tuples: columns are positional
      - scalars: become one-column rows

    `headers` optionally overrides the column names.
    """
    if not records and not headers:
        return ""

    if headers is None:
        if records and isinstance(records[0], dict):
            headers = []
            for record in records:
                for key in record.keys():
                    if key not in headers:
                        headers.append(key)
        else:
            max_len = 0
            for record in records:
                if isinstance(record, (list, tuple)):
                    max_len = max(max_len, len(record))
            headers = list(range(max_len)) if max_len else ["value"]

    if not headers:
        headers = ["value"]

    display_headers = [str(h) for h in headers]

    rows = []
    for record in records:
        if isinstance(record, dict):
            rows.append([_format_cell(record.get(header, "")) for header in headers])

