def print_table(records, headers=None):
    """
    Print a list of dicts or list of lists as an aligned terminal table.

    Args:
        records: List of dicts or list of lists/tuples.
        headers: Optional list of column names.
    """
    if not records:
        print("(no records)")
        return

    # Build header and row data
    if isinstance(records[0], dict):
        if headers is None:
            headers = list(records[0].keys())
        data_rows = [[record.get(h, "") for h in headers] for record in records]
    else:
        if headers is None:
            headers = list(range(len(records[0])))
        data_rows = [list(row) for row in records]

    header = [str(h) for h in headers]
    rows = [[str(v) for v in row] for row in data_rows]

    table = [header] + rows

    # Column widths
    widths = [max(len(row[i]) for row in table) for i in range(len(header))]

    # Detect numeric columns so they can be right-aligned
    numeric_cols = [
        i for i in range(len(header))
        if rows and all(_is_number(row[i]) for row in rows if row[i] != "")
    ]

    def format_cell(value, width, right=False):
        return value.rjust(width) if right else value.ljust(width)

    # Print header
    print("  ".join(
        format_cell(header[i], widths[i], i in numeric_cols)
        for i in range(len(header))
    ))

    # Print separator
    print("  ".join("-" * widths[i] for i in range(len(header))))

    # Print rows
    for row in rows:
        print("  ".join(
            format_cell(row[i], widths[i], i in numeric_cols)
            for i in range(len(header))
        ))

