from difflib import SequenceMatcher


def _normalize(value: str) -> str:
    """Lowercase and collapse whitespace for comparison."""
    return " ".join(value.lower().split())


def similarity(a: str, b: str) -> float:
    """Case-insensitive similarity score between two strings."""
    a = _normalize(a)
    b = _normalize(b)

    if not a or not b:
        return 0.0

    return SequenceMatcher(None, a, b).ratio()


def closest_match(query: str, names: list[str], cutoff: float = 0.6) -> str | None:
    """Return the closest matching name from `names`.

    The match must score at least `cutoff`; otherwise `None` is returned.
    """
    if not names:
        return None

    best_name = None
    best_score = -1.0

    for name in names:
        score = similarity(query, name)
        if score > best_score:
            best_score = score
            best_name = name

    return best_name if best_score >= cutoff else None

