        for header in headers:
            raw = row.get(header, "")
            value = str(raw)

            # Right-align numbers, left-align text
            if isinstance(raw, (int, float)):
                cells.append(value.rjust(col_widths[header]))
            else:
                cells.append(value.ljust(col_widths[header]))

        return "| " + " | ".join(cells) + " |"

    # Print the table
    print(separator)
    print(format_row({h: h for h in headers}))  # header row
    print(separator)

    for record in records:
        print(format_row(record))

