import bcrypt


def hash_password(password: str) -> str:
    """Hash a password using bcrypt with an automatic salt."""
    password_bytes = password.encode("utf-8")

    # bcrypt only uses the first 72 bytes; reject longer passwords
    if len(password_bytes) > 72:
        raise ValueError("Password must be 72 bytes or less when using bcrypt.")

    hashed = bcrypt.hashpw(password_bytes, bcrypt.gensalt(rounds=12))

    # Return the hash as a string; it includes the salt automatically
    return hashed.decode("utf-8")


def verify_password(password: str, password_hash: str) -> bool:
    """Verify a plain text password against a stored bcrypt hash."""
    try:
        return bcrypt.checkpw(
            password.encode("utf-8"),
            password_hash.encode("utf-8"),
        )
    except ValueError:
        return False

