from typing import TypeVar

from pydantic import BaseModel, ValidationError

T = TypeVar("T", bound=BaseModel)


class InvalidRequestBodyError(ValueError):
    """Raised when the request body is missing, invalid, or fails validation."""

    def __init__(self, message: str, errors=None):
        super().__init__(message)
        self.errors = errors or []


def parse_body(model: type[T], body: str | bytes | dict | None) -> T:
    """
    Parse and validate a raw request body into a Pydantic model.

    Accepts:
    - JSON string
    - JSON bytes
    - dict (already JSON-parsed)

    Raises:
    - InvalidRequestBodyError if the body is missing, invalid JSON, or fails validation.
    """
    if body is None:
        raise InvalidRequestBodyError("Request body is required")

    # Reject empty strings/bytes
    if isinstance(body, (str, bytes)) and not body.strip():
        raise InvalidRequestBodyError("Request body is required")

    try:
        if isinstance(body, (str, bytes)):
            # pydantic handles JSON decoding + validation
            return model.model_validate_json(body)

        if isinstance(body, dict):
            return model.model_validate(body)

        raise InvalidRequestBodyError("Request body must be a JSON object")

    except ValidationError as exc:
        raise InvalidRequestBodyError(
            "Invalid request body",
            errors=exc.errors(),
        ) from exc

