    quantity: int = Field(1, ge=1)


def parse_item(raw_body: str) -> Item:
    """Parse JSON string and validate it into an Item.

    Raises ValueError on bad JSON or invalid data.
    """
    try:
        data = json.loads(raw_body)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON body: {exc}") from exc

    try:
        return Item(**data)
    except ValidationError as exc:
        # exc.errors() contains precise field/type/constraint info
        raise ValueError(f"Invalid item data: {exc}") from exc


