"""Helpers for printing records as aligned tables in the terminal."""

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence


def _value_to_str(value: object) -> str:
    if value is None:
        return ""
    return str(value)


def _get_value(record: Mapping, column: str) -> str:
    return _value_to_str(record.get(column, ""))


def format_records(
    records: Iterable[Mapping],
    columns: Sequence[str] | None = None,
) -> str:
    """Format a list of record mappings as an aligned text table."""
    records = list(records)

    if columns is None:
        columns = list(records[0].keys()) if records else []

    headers = [str(column) for column in columns]

    if not records:
        if not headers:
            return "(no records)"
        widths = [len(header) for header in headers]
        header_line = " | ".join(
            header.ljust(width) for header, width in zip(headers, widths)
        )
        separator = "-+-".join("-" * width for width in widths)
        return f"{header_line}\n{separator}"

    rows = [
        [_get_value(record, column) for column in columns]
        for record in records
    ]

    widths = []
    for index, header in enumerate(headers):
        max_width = len(header)
        for row in rows:
            max_width = max(max_width, len(row[index]))
        widths.append(max_width)

    def format_row(values: Sequence[str]) -> str:
        return " | ".join(
            value.ljust(width) for value, width in zip(values, widths)
        )

    table = [
        format_row(headers),
        "-+-".join("-" * width for width in widths),
    ]
    table.extend(format_row(row) for row in rows)

    return "\n".join(table)


def print_records(
    records: Iterable[Mapping],
    columns: Sequence[str] | None = None,
) -> None:
    """Print records as an aligned table."""
    print(format_records(records, columns))

from difflib import SequenceMatcher

def closest_match(query: str, names: list[str], cutoff: float = 0.0) -> str | None:
    """
    Return the closest matching name from `names` to `query`.

    Uses case-insensitive, whitespace-normalized comparison.
    Returns None if no name is at least as similar as `cutoff`.
    """
    def normalize(value: str) -> str:
        return " ".join(value.strip().lower().split())

    normalized_query = normalize(query)
    if not normalized_query or not names:
        return None

    best_name = None
    best_score = -1.0

    for name in names:
        normalized_name = normalize(name)
        score = SequenceMatcher(None, normalized_query, normalized_name).ratio()

        if score > best_score:
            best_score = score
            best_name = name

    if best_score < cutoff:
        return None

    return best_name

