import time
import functools

def ttl_cache(ttl_seconds, maxsize=128):
    def decorator(func):
        cache = {}
        order = []  # simple LRU order (optional)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build a cache key (handle kwargs for completeness)
            key = args + tuple(sorted(kwargs.items()))

            # Check if key exists and not expired
            if key in cache:
                result, timestamp = cache[key]
                if time.time() - timestamp < ttl_seconds:
                    # Optional: move to end (LRU)
                    if key in order:
                        order.remove(key)
                    order.append(key)
                    return result
                else:
                    # expired – delete
                    del cache[key]
                    if key in order:
                        order.remove(key)

            # Compute and store
            result = func(*args, **kwargs)
            cache[key] = (result, time.time())
            order.append(key)

            # Enforce maxsize – remove oldest (FIFO/LRU)
            if len(cache) > maxsize:
                oldest_key = order.pop(0)
                if oldest_key in cache:
                    del cache[oldest_key]

            return result

        # Optional: expose cache inspection/clearing
        wrapper.cache = cache
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper

    return decorator


